test('resource, image and Python guards precede candidate execution; acquisition has no host dependency installer',()=>pass(`
import ast
tree=ast.parse(c.pathlib.Path(c.__file__).read_text())
functions={n.name:n for n in tree.body if isinstance(n,ast.FunctionDef)}
run=functions['run']; inside=functions['inside']
def calls(fn,name):
    return sorted(n.lineno for n in ast.walk(fn) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id==name)
assert len(calls(run,'resource_evidence'))==len(calls(run,'validate_resources'))==2
commands=[n for n in ast.walk(run) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='command']
acq=next(n for n in commands if isinstance(n.args[0],ast.List) and any(isinstance(v,ast.Constant) and v.value=='install' for v in n.args[0].elts))
args=acq.args[0].elts
assert [ast.literal_eval(v) for v in args if isinstance(v,ast.Constant)]==['node','install','chromium','webkit']
assert isinstance(args[1],ast.Call) and args[1].func.id=='str' and args[1].args[0].id=='cli'
assert calls(run,'validate_resources')[0]<acq.lineno<calls(run,'validate_resources')[1]
start=next(n.lineno for n in commands if isinstance(n.args[0],ast.List) and ast.unparse(n.args[0])=="['docker', 'start', '--attach', container]")
assert calls(run,'validate_resources')[1]<start and calls(run,'validate_image')[0]<start
assert calls(inside,'validate_python')[0]<next(n.lineno for n in ast.walk(inside) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='verify_bytes')
assert "[PYTHON,'-I','/inputs/controller.py','--inside']" in c.pathlib.Path(c.__file__).read_text()
`));

